import{_ as i,o as a,c as e,a2 as r}from"./chunks/framework.BXzK3EA4.js";const b=JSON.parse('{"title":"국가 14 아차구의관문국","description":"","frontmatter":{},"headers":[],"relativePath":"world/Cast-State-14.md","filePath":"world/Cast-State-14.md"}'),t={name:"world/Cast-State-14.md"};function h(o,l,u,n,d,s){return a(),e("div",null,[...l[0]||(l[0]=[r('<h1 id="국가-14-아차구의관문국" tabindex="-1">국가 14 아차구의관문국 <a class="header-anchor" href="#국가-14-아차구의관문국" aria-label="Permalink to &quot;국가 14 아차구의관문국&quot;">​</a></h1><p>아차산 능선과 구의 제한 급수, 동부 교량을 현장에서 나누어 쥐는 실세들이다.</p><h3 id="인물-문하율" tabindex="-1">인물 문하율 <a class="header-anchor" href="#인물-문하율" aria-label="Permalink to &quot;인물 문하율&quot;">​</a></h3><ul><li>소속: 아차구의관문국</li><li>직위: 능선 초병</li><li>성격: 직선적이고 산바람보다 회의실을 싫어한다. 한 번 본 불빛은 국적보다 먼저 보고한다.</li><li>개인 야망: 아차산 고지 감시망을 능선수비대 단독 지휘 아래 묶어 물 기술자의 지연을 없앤다.</li><li>공포: 고지가 뚫려 구의 정수와 동부 교량이 같은 밤에 열리는 것.</li><li>통치 방식: 봉화와 호각으로 먼저 막고 사후 승인을 고서준에게 받는다. 평시 공동승인 문서는 초소에 두지 않는다.</li><li>핵심 관계: 고서준의 수비 명령을 최전에서 수행하고, 곽민재의 급수 점검을 감시 공백으로 여기며, 배우진의 후견 제의를 고서준보다 먼저 듣는다.</li><li>촉발 사건: 교량 쪽 상수관 파손 연기를 적대 봉화로 오인해 능선 차단을 먼저 내린다.</li><li>플레이어 개입: 오인 봉화를 정정하거나, 초병의 단독 차단을 전시 통합의 증거로 이용할 수 있다.</li></ul><h3 id="인물-안기준" tabindex="-1">인물 안기준 <a class="header-anchor" href="#인물-안기준" aria-label="Permalink to &quot;인물 안기준&quot;">​</a></h3><ul><li>소속: 아차구의관문국</li><li>직위: 교량 감독</li><li>성격: 점검 해머를 계약서보다 믿지만, 근거 없는 봉쇄는 병력 낭비라고 본다. 교각 균열을 사람 이름처럼 기억한다.</li><li>개인 야망: 광진·구의 동부 교량 통행을 관문국 고유 일정표로 만들어 암사 순찰열차의 임의 정차를 끊는다.</li><li>공포: 교량이 보호정부 명목으로 상수호위단에 넘어가는 것.</li><li>통치 방식: 교각 균열과 통행 무게를 매일 공개하고, 군 통행은 고서준과 물 기술자 회의의 이중 날인을 요구한다.</li><li>핵심 관계: 고서준과 장세화의 통행 협약을 교량에서 집행하고, 심가은의 척후 보고를 검증하며, 남호성의 의무호송을 우선 통과시킨다.</li><li>촉발 사건: 척후대가 상수관 파손을 적대행위로 보고하자 교량을 닫을지 점검만 할지 감독 권한이 쪼개진다.</li><li>플레이어 개입: 파손 원인을 교각 쪽에서 증명하거나, 교량 열쇠를 한쪽 직능에 넘길 수 있다.</li></ul><h3 id="인물-하윤목" tabindex="-1">인물 하윤목 <a class="header-anchor" href="#인물-하윤목" aria-label="Permalink to &quot;인물 하윤목&quot;">​</a></h3><ul><li>소속: 아차구의관문국</li><li>직위: 관문 세리</li><li>성격: 숫자와 인장을 좋아하고, 무력으로 세를 깎는 장교를 모욕으로 기억한다. 빈 면제 칸을 위험 신호로 본다.</li><li>개인 야망: 교량 통과세와 제한 급수 분담금을 하나의 관문 원장으로 합쳐 약소국 공동교섭의 동부 창구가 된다.</li><li>공포: 세리가 보호비 징수원으로 전락해 정유라의 표준 조약에서 제외되는 것.</li><li>통치 방식: 통과 품목과 급수 시간을 같은 장부에 적고, 군사 면제는 계약감사 문구가 있는 통행증만 인정한다.</li><li>핵심 관계: 정유라의 손실보상 조항을 세율에 넣으려 하고, 배우진의 보호세 요구를 거부하며, 라세영의 검역 도장을 세 계산에 연동한다.</li><li>촉발 사건: 세 강국이 서로 다른 급수·통과 면제 문서를 같은 주에 들이민다.</li><li>플레이어 개입: 면제 문서의 진본을 가리거나, 관문 원장을 수서 협약 초안에 실어 나를 수 있다.</li></ul><h3 id="인물-곽민재" tabindex="-1">인물 곽민재 <a class="header-anchor" href="#인물-곽민재" aria-label="Permalink to &quot;인물 곽민재&quot;">​</a></h3><ul><li>소속: 아차구의관문국</li><li>직위: 구의 제한급수 기술자</li><li>성격: 절차를 사랑하고 산악 민병의 속도를 사고 원인으로 본다. 잔압 숫자 없는 명령을 받지 않는다.</li><li>개인 야망: 구의 제한 급수를 뚝도·암사 규격과 호환시켜 생산 주권 없는 물로도 공동규격의 당사자가 되게 한다.</li><li>공포: 능선수비대가 펌프실을 전시 지휘 아래로 넣어 정수 기록이 끊기는 것.</li><li>통치 방식: 급수 시간과 잔압을 게시판에 붙이고, 수비대의 단독 개폐는 기술자 회의 거부권으로 막는다.</li><li>핵심 관계: 고서준과 권한을 다투고, 임초원의 펌프 일지를 구의 잔압 계산에 쓰며, 문하율의 초소 차단이 배관을 얼게 만들까 두려워한다.</li><li>촉발 사건: 상수관 파손 직후 수비대가 펌프실 열쇠를 요구하고 기술자 회의가 거부한다.</li><li>플레이어 개입: 잔압 기록으로 파손이 내부 과압인지 외부 타격인지 밝히거나, 열쇠를 한쪽에 넘길 수 있다.</li></ul><h3 id="인물-심가은" tabindex="-1">인물 심가은 <a class="header-anchor" href="#인물-심가은" aria-label="Permalink to &quot;인물 심가은&quot;">​</a></h3><ul><li>소속: 아차구의관문국</li><li>직위: 교량 척후대장</li><li>성격: 보고를 빨리 쓰지만 해석을 보태는 버릇이 있다. 고서준의 신의에 보답하려 한다.</li><li>개인 야망: 척후대를 관문군 정보 본대로 격상해 물 기술자의 정보 독점도 암사의 후견도 끊는다.</li><li>공포: 오인 보고 한 장이 동부 교량 전쟁으로 번져 자신이 원한의 대상이 되는 것.</li><li>통치 방식: 목격과 추정을 다른 색 먹으로 적게 하지만, 위기 때는 추정 칸을 지우고 목격만 올린다.</li><li>핵심 관계: 고서준에게 직보하고, 안기준의 교량 일정을 방해하며, 장세화의 환승 정보를 맞교환한다.</li><li>촉발 사건: 상수관 파손을 적대행위로 적은 척후 보고가 능선과 교량에 동시에 퍼진다.</li><li>플레이어 개입: 추정 칸의 원본을 공개하거나, 오인 보고를 덮어 수비대 통합을 가속할 수 있다.</li></ul><h3 id="인물-선솔우" tabindex="-1">인물 선솔우 <a class="header-anchor" href="#인물-선솔우" aria-label="Permalink to &quot;인물 선솔우&quot;">​</a></h3><ul><li>소속: 아차구의관문국</li><li>직위: 구의 펌프실 정비사, 곽민재의 실무 담당자</li><li>성격: 임펠러 이빨의 마모를 손가락으로 읽고, 구두 개폐는 키 걸이못에 걸지 않는다. 교각 금속음을 패킹 교체 순서로 외운다.</li><li>개인 야망: 펌프 패킹과 임펠러 교체 주기를 관문 공개 마모표로 고정해, 능선이 열쇠를 가져가도 급수 품질이 숫자로 남게 한다.</li><li>공포: 능선 초병이 걸이못을 호각으로 비워 정수 일지가 한 밤에 공백이 되는 것.</li><li>통치 방식: 마모표와 패킹 날을 벽에 걸고, 수비대 단독 개폐는 정비 키가 걸이못에 있을 때만 가능하다.</li><li>핵심 관계: 곽민재의 잔압 식을 임펠러 이빨에 맞추는 사제이고, 문하율의 능선 감시가 배관을 얼리기 전에 개폐 시각을 맞춘다. 고서준의 관문 수리가 펌프실 키를 빌려 가면 마모표에 빈칸을 남긴다.</li><li>촉발 사건: 상수관이 터진 직후 수비대가 키를 요구하자 선솔우는 걸이못을 비우지 않고 마모표에 파손 시각만 적었다.</li><li>플레이어 개입: 이빨 마모표를 파손 시각과 겹쳐 읽거나, 걸이못의 키를 능선 호각과 기술자 회의 중 어디에 걸지 정할 수 있다.</li></ul><h3 id="인물-원예나" tabindex="-1">인물 원예나 <a class="header-anchor" href="#인물-원예나" aria-label="Permalink to &quot;인물 원예나&quot;">​</a></h3><ul><li>소속: 아차구의관문국</li><li>직위: 교량 통과 물류상</li><li>성격: 통행 무게와 교각 균열을 같은 저울에 올리고, 근거 없는 봉쇄를 병력 낭비라고 본다. 빈 면제 칸이 찍힌 송장을 위험 신호로 본다.</li><li>개인 야망: 광진·구의 동부 교량 화물을 관문국 고유 일정표로만 움직여 암사 순찰열차의 임의 정차를 끊는다.</li><li>공포: 교량 화물이 보호정부 명목으로 상수호위단에 넘어가 세리 원장이 빈 종이가 되는 것.</li><li>통치 방식: 교각 균열과 통행 무게를 매일 공개하고, 군 통행 송장은 고서준과 물 기술자 회의의 이중 날인이 있기 전에는 싣지 않는다.</li><li>핵심 관계: 안기준의 교량 일정을 화물 순서로 집행하는 계약이고, 원다결의 관문 저울에 무게를 맞춘다. 남호성의 의무호송을 우선 통과시킨다.</li><li>촉발 사건: 척후대가 상수관 파손을 적대행위로 보고하자 원예나는 군 통행 송장을 봉인하고 점검 무게만 남겼다.</li><li>플레이어 개입: 파손 원인을 화물 무게로 증명하거나, 교량 열쇠를 한쪽 직능에 넘길 수 있다.</li></ul><h3 id="인물-영석온" tabindex="-1">인물 영석온 <a class="header-anchor" href="#인물-영석온" aria-label="Permalink to &quot;인물 영석온&quot;">​</a></h3><ul><li>소속: 아차구의관문국</li><li>직위: 능선·교량 당직 의무원</li><li>성격: 고지 바람보다 상처의 열을 먼저 읽고, 초병의 단독 차단을 진료 중단의 원인으로 적는다. 적의 부상도 활력이 떨어지면 같은 들것으로 본다.</li><li>개인 야망: 능선과 교량 사이 응급 이송을 약령 의무호송과 한 장의 호송증으로 묶어 관문국이 치료 회랑의 한쪽 기둥이 되게 한다.</li><li>공포: 고지가 뚫린 밤에 의무소가 전리품 창구로 바뀌고 잔압 기록과 병상이 함께 비는 것.</li><li>통치 방식: 중증도 표와 급수 시간을 같은 칠판에 붙이고, 전시 단독지휘 쪽지는 기술자 회의 거부권이 풀리기 전에는 침상에 들이지 않는다.</li><li>핵심 관계: 영한뫼의 교량 의무소와 병상을 나누고, 남호성의 호송증을 당직 원장에 옮긴다. 류은비의 치료 원칙을 고지 침상에도 붙인다.</li><li>촉발 사건: 교량 쪽 상수관 파손 연기를 적대 봉화로 오인한 밤, 의무소 대기표에 무장 대기열이 한 줄 끼어 있었다.</li><li>플레이어 개입: 무장 줄을 환자 줄과 분리하거나, 호송증 초안을 약령까지 운반할 수 있다.</li></ul><h3 id="인물-판늘샘" tabindex="-1">인물 판늘샘 <a class="header-anchor" href="#인물-판늘샘" aria-label="Permalink to &quot;인물 판늘샘&quot;">​</a></h3><ul><li>소속: 아차구의관문국</li><li>직위: 아차산 능선 순찰대, 문하율의 실무 담당자</li><li>성격: 한 번 본 불빛은 국적보다 먼저 보고하고, 회의실의 사후 승인을 초소에 두지 않는다. 직선적이고 산바람보다 인장을 싫어한다.</li><li>개인 야망: 아차산 고지 감시망을 능선수비대 단독 순찰 시계로 묶어 물 기술자의 지연을 없앤다.</li><li>공포: 고지가 뚫려 구의 정수와 동부 교량이 같은 밤에 열리는 것.</li><li>통치 방식: 봉화와 호각으로 먼저 막고 사후 승인을 고서준에게 받되, 평시 공동승인 문서는 초소 벽에 붙이지 않는다.</li><li>핵심 관계: 문하율의 지휘로 능선을 돌고, 선늘봄의 초소 당직과 호각을 나눈다. 배우진의 후견 제의를 고서준보다 먼저 듣지 않는다.</li><li>촉발 사건: 교량 쪽 상수관 파손 연기를 적대 봉화로 오인해 판늘샘이 능선 차단을 먼저 내렸다.</li><li>플레이어 개입: 오인 봉화를 정정하거나, 초병의 단독 차단을 전시 통합의 증거로 이용할 수 있다.</li></ul><h3 id="인물-천초윤" tabindex="-1">인물 천초윤 <a class="header-anchor" href="#인물-천초윤" aria-label="Permalink to &quot;인물 천초윤&quot;">​</a></h3><ul><li>소속: 아차구의관문국</li><li>직위: 관문 공동승인 전령, 하윤목의 실무 담당자</li><li>성격: 봉인 끈이 느슨하면 출발을 거부하고, 빈 면제 칸이 찍힌 전갈을 사고 원인으로 본다. 숫자와 인장을 사람 말보다 믿는다.</li><li>개인 야망: 교량 통과세와 제한 급수 분담금 통지를 자신이 날인하는 전령 원장에만 유효하게 해 약소국 공동교섭의 동부 창구를 지킨다.</li><li>공포: 세 강국의 서로 다른 면제 전갈이 같은 주에 붙어 세리가 보호비 징수원으로 찍히는 것.</li><li>통치 방식: 통과 품목과 급수 시간을 같은 전갈에 적고, 군사 면제는 계약감사 문구가 있는 통행증만 배달한다.</li><li>핵심 관계: 하윤목의 관문 원장을 봉인 상태로만 나르는 지휘를 받고, 영한뫼의 통과 원장과 순번을 나눈다. 정유라의 손실보상 조항을 전갈 말미에 옮기려 한다.</li><li>촉발 사건: 세 강국이 서로 다른 급수·통과 면제 문서를 같은 주에 들이밀자 천초윤은 면제 전갈을 가방에 잠그고 진본 대조를 요구했다.</li><li>플레이어 개입: 면제 문서의 진본을 가리거나, 관문 원장을 수서 협약 초안에 실어 나를 수 있다.</li></ul><h3 id="인물-동새봄" tabindex="-1">인물 동새봄 <a class="header-anchor" href="#인물-동새봄" aria-label="Permalink to &quot;인물 동새봄&quot;">​</a></h3><ul><li>소속: 아차구의관문국</li><li>직위: 교량 하부 탐사원, 심가은의 실무 담당자</li><li>성격: 목격과 추정을 다른 색 먹으로 적게 하지만, 위기 때는 추정 칸을 지우고 금이 간 관만 남긴다. 보고를 빨리 쓰되 해석을 보태는 상관의 버릇을 현장에서 깎는다.</li><li>개인 야망: 교량 하부와 상수관 파손 좌표를 공개 원판에 묶어 물 기술자의 정보 독점도 암사의 후견도 끊는다.</li><li>공포: 오인 실선 한 줄이 동부 교량 전쟁으로 번져 자신이 원한의 대상이 되는 것.</li><li>통치 방식: 실측하지 않은 파손은 점선으로만 남기고, 적대행위 문장은 고서준의 직보 전에는 원판에 옮기지 않는다.</li><li>핵심 관계: 심가은의 척후 보고를 좌표로 번역하는 사제이고, 안기준의 교각 균열 이름을 원판 여백에 적는다. 장세화의 환승 정보를 점선으로만 맞교환한다.</li><li>촉발 사건: 상수관 파손을 적대행위로 적은 척후 보고가 능선과 교량에 동시에 퍼지자 동새봄은 추정 칸을 지우고 금 간 관만 공개했다.</li><li>플레이어 개입: 추정 칸의 원본을 공개하거나, 오인 실선을 덮어 수비대 통합을 가속할 수 있다.</li></ul><h3 id="인물-방마름" tabindex="-1">인물 방마름 <a class="header-anchor" href="#인물-방마름" aria-label="Permalink to &quot;인물 방마름&quot;">​</a></h3><ul><li>소속: 아차구의관문국</li><li>직위: 관문 통과 기록관, 하윤목의 실무 담당자</li><li>성격: 빈 면제 칸을 위험 신호로 보고, 무력으로 세를 깎는 장교의 이름을 원장 난외에 오래 남긴다. 숫자와 인장을 좋아한다.</li><li>개인 야망: 교량 통과세와 제한 급수 분담금을 하나의 관문 원장으로 합쳐 정유라의 표준 조약에서 동부 창구가 빠지지 않게 한다.</li><li>공포: 원장이 보호비 징수 장부로 전락해 약소국 공동교섭에서 제외되는 것.</li><li>통치 방식: 통과 품목과 급수 시간을 같은 장부에 적고, 군사 면제는 계약감사 문구가 있는 통행증만 유효 칸에 올린다.</li><li>핵심 관계: 하윤목의 세 계산을 원장으로 옮기는 사제이고, 천초윤의 전갈 사본을 같은 줄에 남긴다. 라세영의 검역 도장을 세 칸에 연동한다.</li><li>촉발 사건: 세 강국이 서로 다른 급수·통과 면제 문서를 들이밀자 방마름은 세 장을 난외로 내리고 진본 대조가 끝나기 전에 날인을 열지 않았다.</li><li>플레이어 개입: 난외 면제 장을 공개하거나, 원장 한 줄을 지워 세리를 보호 징수원으로 몰 수 있다.</li></ul><h3 id="인물-수지완" tabindex="-1">인물 수지완 <a class="header-anchor" href="#인물-수지완" aria-label="Permalink to &quot;인물 수지완&quot;">​</a></h3><ul><li>소속: 아차구의관문국</li><li>직위: 구의역 대합실 거점장</li><li>성격: 승강장 진동으로 교량 무게를 가늠하고, 군수 화차를 제한 급수 대기열 앞으로 끌어오라는 명령을 모욕으로 듣는다. 온화하나 봉화가 뜨면 방송을 직접 잡는다.</li><li>개인 야망: 구의 대합실을 급수 게시·교량 통행·의무호송이 한 지붕에서 서명되는 관문 창구로 남겨 보호정부 명목의 정차를 승강장에 들이지 못하게 한다.</li><li>공포: 상수관 파손 소문만으로 대합실이 봉쇄되고 주민이 후문 밀차로 흩어지는 것.</li><li>통치 방식: 대합실 급수 시간과 통행 대기표를 매일 공개하고, 군수 화차는 의무호송이 떠난 뒤에만 승강장에 붙인다.</li><li>핵심 관계: 안기준의 교량 일정을 승강장 칠판에 옮기고, 영한뫼의 의무 대기와 줄을 나눈다. 남호성의 호송 정차를 우선 칸에 둔다.</li><li>촉발 사건: 척후 보고가 적대행위로 퍼진 날, 구의 대합실 대기표에 군수 문장 상자가 한 줄 끼어 있었다.</li><li>플레이어 개입: 대합실 화물을 공개 검수하거나, 급수 줄을 군수 대기열과 분리할 수 있다.</li></ul><h3 id="인물-선늘봄" tabindex="-1">인물 선늘봄 <a class="header-anchor" href="#인물-선늘봄" aria-label="Permalink to &quot;인물 선늘봄&quot;">​</a></h3><ul><li>소속: 아차구의관문국</li><li>직위: 능선 초소 기지 당직장, 문하율의 실무 담당자</li><li>성격: 초소 당직을 집처럼 여기고, 공동승인 문서를 초소에 두라는 쪽지를 태운다. 한 번 본 불빛을 교대 일지에 먼저 적는다.</li><li>개인 야망: 아차산 초소를 능선수비대 고유 거점으로 남겨 물 기술자의 지연과 암사 후견이 같은 지붕 아래 서지 못하게 한다.</li><li>공포: 초소 당직이 오인 봉화의 발판이 되어 고지와 교량이 같은 밤에 열리는 것.</li><li>통치 방식: 당직 명과 봉화 시각을 같은 칠판에 붙이고, 외부 무장 접근은 고서준의 동행 없이 막는다.</li><li>핵심 관계: 문하율의 초병 명령을 기지에서 집행하고, 판늘샘의 순찰 호각을 당직과 나눈다. 곽민재의 급수 점검을 감시 공백으로 여기지 않으려 일지를 겹친다.</li><li>촉발 사건: 상수관 파손 연기를 적대 봉화로 오인한 밤, 초소 당직 명단이 한 줄 빠져 있었다.</li><li>플레이어 개입: 빠진 당직자를 찾거나, 초소 봉화를 이중 열쇠로 바꿀 수 있다.</li></ul><h3 id="인물-원다결" tabindex="-1">인물 원다결 <a class="header-anchor" href="#인물-원다결" aria-label="Permalink to &quot;인물 원다결&quot;">​</a></h3><ul><li>소속: 아차구의관문국</li><li>직위: 관문 통과 시장 거점장</li><li>성격: 통과세를 숨기는 상인을 저울 앞에서 돌려보내고, 군사 면제 칸을 시세로 파는 말을 시장에서 쫓아낸다. 공개 저울을 신용으로 본다.</li><li>개인 야망: 관문 시장을 통과세와 급수 분담금의 공개 시세 거점으로 남겨 보호비가 시장 칸을 사지 못하게 한다.</li><li>공포: 시장 재고가 군수 전용으로 빠져 제한 급수 주민의 하루치가 빈 상자가 되는 것.</li><li>통치 방식: 시세와 통과 품목을 벽에 적고, 면제 문장이 찍힌 주문서는 하윤목의 원장 게시 전까지 출고를 막는다.</li><li>핵심 관계: 원예나의 교량 송장과 시세를 맞추고, 방마름의 세 칸을 시장 원장에 옮긴다. 남윤경의 비상 시세 제의를 원한으로 돌려보낸다.</li><li>촉발 사건: 세 강국 면제 문서가 같은 주에 들어오자 원다결은 군수 명목의 출고를 거부하고 실재고만 저울에 올렸다.</li><li>플레이어 개입: 면제 주문서를 공개하거나, 급수 물자 우선 칸을 시장 원장에 고정할 수 있다.</li></ul><h3 id="인물-영한뫼" tabindex="-1">인물 영한뫼 <a class="header-anchor" href="#인물-영한뫼" aria-label="Permalink to &quot;인물 영한뫼&quot;">​</a></h3><ul><li>소속: 아차구의관문국</li><li>직위: 교량 의무소 거점장</li><li>성격: 들것 순서를 국적보다 앞에 두고, 봉쇄대의 무장 대기를 침상 앞으로 들이라는 쪽지를 찢는다. 온화하나 상수관 파손 소문이 뜨면 문을 직접 잠근다.</li><li>개인 야망: 교량 의무소를 관문국 고유 진료 거점으로 남겨 강국 호위병이 병상 옆에 서는 관행을 없앤다.</li><li>공포: 의무소가 적대 이동의 대기실로 오인되어 호송 전체가 무장 해제를 당하는 것.</li><li>통치 방식: 중증도 표와 급수 시간을 문에 붙이고, 무기함 봉인은 통행 심사 입회 없이 열지 않는다.</li><li>핵심 관계: 영석온의 당직 침상과 병상을 나누고, 수지완의 대합실 대기와 줄을 맞춘다. 남호성의 의무호송을 도착 확인에 쓴다.</li><li>촉발 사건: 상수관 파손을 적대행위로 적은 보고가 퍼진 밤, 의무소 당직 명단이 한 줄 빠져 있었다.</li><li>플레이어 개입: 빠진 당직자를 찾거나, 의무소를 개방 진료로 되돌려 봉쇄를 흔들 수 있다.</li></ul><h3 id="인물-판초담" tabindex="-1">인물 판초담 <a class="header-anchor" href="#인물-판초담" aria-label="Permalink to &quot;인물 판초담&quot;">​</a></h3><ul><li>소속: 아차구의관문국</li><li>직위: 구의 펌프실 비상발전 운전장</li><li>성격: 연료 냄새에 예민하고 구두 배전을 싫어한다. 정수 펌프보다 능선 조명에 전력을 돌리라는 압박을 모욕으로 여긴다.</li><li>개인 야망: 펌프실과 의무소 전력을 하나의 공개 배전망으로 묶어 제한 급수의 품질 주권을 지킨다.</li><li>공포: 연료가 바닥난 밤에 잔압이 떨어지고, 그 공백을 암사 보호권이 메우는 것.</li><li>통치 방식: 매 교대 연료 잔량과 출력 일지를 봉인해 선솔우에게 보내고, 최저 출력 이하면 수비대장의 독촉이 있어도 봉화 배전을 끊는다.</li><li>핵심 관계: 선솔우의 펌프에 출력을 맞추고, 영한뫼의 의무소 전력을 같은 일지에 남긴다. 고서준의 전시 지휘에는 복종하되 은폐 배전은 거부한다.</li><li>촉발 사건: 상수관 파손과 정전이 겹치자 판초담은 비상 발전을 펌프와 의무소에 잠그고 능선 조명을 껐다.</li><li>플레이어 개입: 대체 연료를 구해 이중 배전을 열거나, 출력 일지 조작을 밝혀 운전장을 교체할 수 있다.</li></ul><h3 id="인물-매서담" tabindex="-1">인물 매서담 <a class="header-anchor" href="#인물-매서담" aria-label="Permalink to &quot;인물 매서담&quot;">​</a></h3><ul><li>소속: 아차구의관문국</li><li>직위: 관문 통행 증인</li><li>성격: 교량 통과증의 접힌 자국까지 기억하고, 군사 면제 칸을 증언으로 포장하는 사신을 내려보낸다. 침묵이 길수록 증언은 짧다.</li><li>개인 야망: 동부 도하 통과의 실제 시각을 공개 증언으로 남겨 오인 봉화가 다시 의무호송을 적으로 찍지 못하게 한다.</li><li>공포: 자신의 증언이 봉쇄대의 면죄부가 되어 고서준의 공동통치가 한쪽 칼만 남는 것.</li><li>통치 방식: 통과 시각과 봉화 색을 같은 칠판에 적고, 면제 문장이 찍힌 증언은 하윤목의 원장 게시 전까지 봉한다.</li><li>핵심 관계: 고서준의 교량 허가와 증언을 겹치고, 범초이의 호송 사고 진술과 시각을 맞춘다. 하윤목의 통과 원장을 증인석의 뼈대로 둔다.</li><li>촉발 사건: 겨울의 검은 배차표가 열리자 아차 척후가 의무호송을 적대 이동으로 오인했고 매서담은 그 밤의 봉화 색을 증인으로 남겼다.</li><li>플레이어 개입: 봉화 일지를 공개해 오인을 풀거나, 증언을 봉쇄 구실로 넘길 수 있다.</li></ul><h3 id="인물-탁윤재" tabindex="-1">인물 탁윤재 <a class="header-anchor" href="#인물-탁윤재" aria-label="Permalink to &quot;인물 탁윤재&quot;">​</a></h3><ul><li>소속: 아차구의관문국</li><li>직위: 교량 통행 사고 당사자</li><li>성격: 난간 충격의 각도를 몸으로 기억하고, 급수 호스를 군수 줄로 바꾸라는 쪽지를 태운다. 말은 짧고 발자국은 정확하다.</li><li>개인 야망: 구의 교량 충돌의 당사자 진술을 관문 원장에 고정해 제한 급수 주민의 하루치가 빈 상자가 되지 않게 한다.</li><li>공포: 사고 칸이 보호군 진입의 발판으로 찍혀 자신이 없는 전쟁의 구실이 되는 것.</li><li>통치 방식: 충돌 시각과 잔압 수치를 같은 일지에 적고, 외부 무장 접근은 고서준의 동행 없이 증언에서 뺀다.</li><li>핵심 관계: 선솔우의 펌프 일지와 잔압을 맞추고, 영한뫼의 의무소 들것과 사고 줄을 나눈다. 한재목의 급수 연장 제의를 사고 뒤에만 읽는다.</li><li>촉발 사건: 개막일 세 번째 급수계약이 만료되며 의료호송이 지연되자 탁윤재의 급수 수레가 구의 교량에서 호송칸과 부딪쳤다.</li><li>플레이어 개입: 당사자 진술로 잔압 사고를 밝히거나, 충돌을 적대행위로 고쳐 쓸 수 있다.</li></ul><h3 id="인물-범한들" tabindex="-1">인물 범한들 <a class="header-anchor" href="#인물-범한들" aria-label="Permalink to &quot;인물 범한들&quot;">​</a></h3><ul><li>소속: 아차구의관문국</li><li>직위: 급수계약 만료 증인</li><li>성격: 만료일을 손가락으로 세고, 구두로 보호 연장을 증언하자는 사신을 증인석에서 내려보낸다. 숫자는 믿되 빈칸 조항은 믿지 않는다.</li><li>개인 야망: 구의 제한 급수의 종료 조건을 공개 증언으로 고정해 세 강국이 서로 다른 문안으로 관문을 쪼개지 못하게 한다.</li><li>공포: 자신이 서명한 증언이 집단 단수의 면죄부가 되는 것.</li><li>통치 방식: 만료 시각과 잔량 표를 같은 책에 붙이고, 인장이 마르기 전의 사본은 증언에서 뺀다.</li><li>핵심 관계: 곽민재의 급수 점검을 증인석에서 받치고, 임하준의 실종 뒤에 남은 만료 표시를 증언의 뼈대로 삼는다. 한재목의 서부 문안을 읽어 주되 날인은 미룬다.</li><li>촉발 사건: 개막일 세 번째 급수계약이 총관 실종과 함께 만료되자 범한들은 세 강국의 면제 문안을 한 자리에 놓고 증언을 멈췄다.</li><li>플레이어 개입: 단수 조항을 뺀 수정본을 증인석에 올리거나, 증인이 받은 급수 사례를 원장에 올릴 수 있다.</li></ul><h3 id="인물-창지안" tabindex="-1">인물 창지안 <a class="header-anchor" href="#인물-창지안" aria-label="Permalink to &quot;인물 창지안&quot;">​</a></h3><ul><li>소속: 아차구의관문국</li><li>직위: 보호권 징발 피난 인파 대표</li><li>성격: 능선 초소의 빈집을 먼저 세고, 수비대를 보호군 선발로 부르라는 방송을 모욕으로 듣는다. 줄이 길어질수록 목소리는 낮아진다.</li><li>개인 야망: 관문 인파의 징발 명단을 공개 거부 원장으로 묶어 고지와 교량이 같은 밤에 보호권으로 열리지 않게 한다.</li><li>공포: 대표로 나선 자신의 이름이 동부 후견 명부의 맨 위가 되는 것.</li><li>통치 방식: 징발 쪽지와 실제 통행 인원을 저녁마다 대조하고, 고서준의 공동통치 선언이 내려오기 전에는 인파를 해산시키지 않는다.</li><li>핵심 관계: 문하율의 초소 당직과 인파 줄을 나누고, 석봄우의 환승 거부 문구와 문장을 맞춘다. 배우진의 동부 후견 제안을 원한으로 돌려보낸다.</li><li>촉발 사건: 둘째 해 여름 이후 다섯 통일안 가운데 상수보호권이 패권전으로 번지자 창지안은 아차산 기슭의 징발 인파를 대표해 봉화 스위치를 잠갔다.</li><li>플레이어 개입: 거부 원장을 약소국 회의에 올리거나, 인파를 해산시켜 보호군 통과를 열 수 있다.</li></ul><h3 id="인물-초태온" tabindex="-1">인물 초태온 <a class="header-anchor" href="#인물-초태온" aria-label="Permalink to &quot;인물 초태온&quot;">​</a></h3><ul><li>소속: 아차구의관문국</li><li>직위: 약소국 회의 관문 증인</li><li>성격: 회의 호송의 통과 시각을 봉인보다 먼저 확인하고, 구두 합의를 통행증으로 바꾸려는 사신을 문 앞에 세운다. 예의는 지키되 날짜를 고치는 손은 용서하지 않는다.</li><li>개인 야망: 열한 자리 회의 호송이 관문을 지나는 기록을 공개 증언으로 남겨 분할 복속의 쪽지가 교량을 먼저 건너지 못하게 한다.</li><li>공포: 위조 회의 통과증 한 장이 약소국을 강국별로 쪼개 증인석이 매수의 창구가 되는 것.</li><li>통치 방식: 통과 전갈을 관문과 회의장에 동시에 남기고, 암살·매수 소문은 증인 없이 원장에 올리지 않는다.</li><li>핵심 관계: 정유라의 공동교섭 호송을 관문에서 증언하고, 근주하의 서명 원장과 시각을 맞춘다. 장세화의 상호호송 초안을 회의 전에만 펼친다.</li><li>촉발 사건: 둘째 해 봄 열한 자리 회의가 열리자 초태온은 강국별 분할 복속 쪽지가 든 호송칸을 교량 앞에서 세우고 공동헌장 사본만 통과시켰다.</li><li>플레이어 개입: 세운 칸의 쪽지를 폭로하거나, 공동헌장 증인을 호송해 관문 원장을 지킬 수 있다.</li></ul><h3 id="인물-석주아" tabindex="-1">인물 석주아 <a class="header-anchor" href="#인물-석주아" aria-label="Permalink to &quot;인물 석주아&quot;">​</a></h3><ul><li>소속: 아차구의관문국</li><li>직위: 열여섯 깃발 관문 인준 관계자</li><li>성격: 헌장 사본의 접힌 자국까지 기억하고, 늦게 온 인준을 소급하자고 하면 함을 잠근다. 날짜를 고치는 손을 관문 위에서 용서하지 않는다.</li><li>개인 야망: 관문국의 깃발 인준 원본을 구의 함에만 유효하게 남겨 명목 권위가 사후 날인으로 팔리지 않게 한다.</li><li>공포: 인준 함이 강국의 보호 문장으로 덧칠되어 관문 헌장이 하청 문서가 되는 것.</li><li>통치 방식: 깃발 인준일을 능선 벽에 적고, 사후 추인 청구는 당시 증인 두 명이 다시 서지 않으면 받지 않는다.</li><li>핵심 관계: 고서준이 맡긴 건국 인준 함을 지키고, 윤서린의 도성 인준 날짜와 대조한다. 심가은의 공동승인 문서와 보관 주기를 맞춘다.</li><li>촉발 사건: 붕괴 3년 열여섯 깃발이 선언될 때 석주아는 도성 인준을 받은 관문 헌장과 받지 않은 통행 관습을 따로 접어 두었다.</li><li>플레이어 개입: 접힌 목록을 공개해 빚을 드러내거나, 함이 덧칠되기 전에 원본을 호송할 수 있다.</li></ul><h3 id="인물-근바름" tabindex="-1">인물 근바름 <a class="header-anchor" href="#인물-근바름" aria-label="Permalink to &quot;인물 근바름&quot;">​</a></h3><ul><li>소속: 아차구의관문국</li><li>직위: 공동호송 서명 보조</li><li>성격: 먹물이 마르기 전의 구두 통과를 보조 서명으로 치지 않는다. 조용하나 교량 조항이 비면 붓을 내려놓는다.</li><li>개인 야망: 교량 통과와 비상 급수를 한 장의 보조 원장으로 묶어 보호비가 서명란을 사지 못하게 한다.</li><li>공포: 위조 정서본이 보조 함에 섞여 자신이 오인 봉화의 손이 되는 것.</li><li>통치 방식: 보조 서명 시각과 증인 이름을 같은 줄에 적고, 인장이 둘 미만이면 함을 잠근다.</li><li>핵심 관계: 초나루의 신내 서기 원장과 조항 번호를 맞추고, 창해온의 의료 조항을 교량 칸에 옮긴다. 고서준의 공동통치 날인만 보조 함의 열쇠로 둔다.</li><li>촉발 사건: 붕괴 5년 둘째 급수협약이 비상 호송 조건을 다시 정하자 근바름은 구의 교량 통과를 보조 서명으로 남기고 보호조항 쪽지를 함 아래에 넣었다.</li><li>플레이어 개입: 함 아래 쪽지를 꺼내 폭로하거나, 보조 증인을 호송해 교량 조항을 지킬 수 있다.</li></ul>',50)])])}const q=i(t,[["render",h]]);export{b as __pageData,q as default};
